    uid: "sxsw-2026-0802-scrappy-startups-meetup-4@manual",
    summary: "Scrappy Startups Meetup #4",
    description: "About: Welcome to Scrappy Startups Meetup #4, a monthly event for founders, aspiring founders, and business owners all over Austin. Street Parking in the area is free after 6pm, or come see Will for parking validation during the event. Agenda 6:00 PM – 6:30 PM: Open Networking Kick off the evening by meeting other attendees using Reuneo and getting settled. 6:30 PM – 7:00PM: The Topic Will and Dom briefly introduce themselves, share the goals of the event, and gather input from attendees on topics for future meetups. 6:45 PM – 8:00PM: Focused Networking Continue conversations, share takeaways, and connect with others about the ideas, challenges, and opportunities discussed during the event. Free Food & Drinks Beer Soda Water Food Who Should Come We welcome both founders and non-founders interested in learning more about how to run a company, business/personal finance, and clever ways to make and save money. Sponsors happyhopper - Find food and drink deals near you, in every major US and Canadian City. Download our App 10 Pillar Productions - We collaborate with brands, marketing agencies, and fellow filmmakers to produce high-quality commercials and films throughout the state of Texas. Check out our website. Station Austin - Thank you to Station Austin for sponsoring Scrappy Startups. Station Austin is the center of gravity for entrepreneurs in Texas. They bring together the best entrepreneurs in the state and connect them with their first investors, employees, mentors, and customers. To sign up for a Station Austin membership, click here Future Sponsors Interested in sponsoring a future Scrappy Startups meetup? Reach out to Will or Dom. Contact If you have any questions, please reach out to Will - will@happyhopper.app",
