    summary: "Fast lanes, faster attacks: An evening of karting with Kodem",
    description: "Security moves fast. Attackers move faster. Join us at Circuit of the Americas for a private evening with security leaders and operators. We’ll start on the track with a competitive karting session, then shift to conversation over drinks and dinner with a small group of CISOs and security engineering leaders. Open discussion on what’s actually working in today’s environment, from AI in production to software supply chain risk and closing the gap between security and engineering. What to expect: Private karting experience at COTA Small group of senior security leaders Candid conversation, no pitches Food and drinks throughout the evening Spots are limited.",
