    uid: "sxsw-2026-0810-cipherhacks@manual",
    summary: "Cipherhacks",
    description: "Greetings, seeker, we cordially invite you to another Hackathon at ACC This semester's theme revolves around cryptography and digital rights as well as making software that empowers the user. Participants will be judged on effort, thinking process and merit, which will allow AI, template-based, and traditional programmers, to compete with fair footing. Regardless of the tools, an engineer must apply critical thinking, a designer must dream. Theme Cryptography Digital Rights & Human Rights Privacy Tools Journalism Tools Digital Sovereignty Prize Catagories: 1st Place -Mega swag 2nd Place - Cool swag 3rd Place - Swag swag Challenge Areas: Locate a challenge in privacy and create a solution for it Decentralized communication Infographic Website covering a topic related to cryptography and digital rights Example ideas: Steganography Software Panic button apps for NGOs Create an ARG like Cicada 3301, encourage users to utilize privacy-preserving technology Can the i2p protocol be more user friendly?",
